import re
import time

def search_pattern(pattern: str, content: str) -> bool:
    try:
        # Add a time limit to prevent ReDoS attacks
        start_time = time.time()
        match = re.search(pattern, content)
        # Timeout after 1 second to mitigate ReDoS
        if time.time() - start_time > 1:
            return False
        return bool(match)
    except re.error:
        return False
    except Exception:
        return False
